const item = $input.item.json.output;
const hasOrderId = item["Order ID"] && item["Order ID"] !== "Not Provided";

// Handle either single-item or Items[] array shape from the extraction agent
const firstItem = item.Items?.[0] || item;

return {
  json: {
    ...item,
    searchMode: hasOrderId ? "orderId" : "nameProductSku",
    searchOrderId: hasOrderId ? item["Order ID"] : null,
    searchCustomerName: item["Customer Name"],
    searchProductName: firstItem["Product Name"],
    searchSku: firstItem["SKU"]
  }
};

const criteria = $('Build Search Criteria').item.json;
const matches = [];

const normalize = (str) => (str || "").toString().trim().toLowerCase();

const hasSku = criteria.searchSku && normalize(criteria.searchSku) !== "not provided";

// Helper: does the row's product reasonably match what the customer described?
function productReasonablyMatches(row, criteria) {
  const rowProduct = normalize(row["Product Name"]);
  const statedProduct = normalize(criteria.searchProductName);

  if (!statedProduct) return true; // customer gave no product description to check against

  return rowProduct.includes(statedProduct.replace(/\bshirt\b/g, "").trim())
      || statedProduct.includes(rowProduct);
}

for (const item of $input.all()) {
  const row = item.json;
  if (!row || Object.keys(row).length === 0) continue;

  let isMatch;

  if (criteria.searchMode === "orderId") {
    isMatch = normalize(row["Order ID"]) === normalize(criteria.searchOrderId);
  } else if (hasSku) {
    isMatch = normalize(row["SKU"]) === normalize(criteria.searchSku)
              && normalize(row["Customer Name"]) === normalize(criteria.searchCustomerName);
  } else {
    const nameMatches = normalize(row["Customer Name"]) === normalize(criteria.searchCustomerName);
    const productMatches = productReasonablyMatches(row, criteria);
    isMatch = nameMatches && productMatches;
  }

  if (isMatch) matches.push(item);
}

if (matches.length === 0) {
  return [{ json: { row_number: null, noMatch: true, productMismatch: false } }];
}

// --- NEW: even when Order ID matched, verify the product actually lines up ---
const matchedRow = matches[0].json;
const productMismatch = criteria.searchMode === "orderId"
  ? !productReasonablyMatches(matchedRow, criteria)
  : false;

return [{
  json: {
    ...matchedRow,
    noMatch: false,
    productMismatch
  }
}];

const order = $input.item.json.output;
const products = order.Products;

const cityCodeMap = {
  "Lahore DC": "LHR",
  "Karachi DC": "KHI",
  "Islamabad DC": "ISB"
};

// --- Helper: extract a parseable date from a raw email "received" header block ---
function extractDateFromReceivedHeader(raw) {
  if (!raw) return null;
  const match = raw.toString().match(/\w{3},\s\d{1,2}\s\w{3}\s\d{4}\s\d{2}:\d{2}:\d{2}\s[+-]\d{4}/);
  return match ? match[0] : raw;
}

// --- Helper: robustly parse a date string in various formats ---
function parseFlexibleDate(raw) {
  if (!raw) return new Date(NaN);
  return new Date(raw.toString().trim());
}

// Group products by warehouse city so multi-warehouse orders get separate Order IDs
const groups = {};
for (const product of products) {
  const city = product["Warehouse Location"];
  if (!groups[city]) groups[city] = [];
  groups[city].push(product);
}

// --- Delivery date = date the email was received + 4 days ---
const orderDate = new Date(order["Date Of Order"]);
const deliveryDate = new Date(orderDate);
deliveryDate.setDate(deliveryDate.getDate() + 4);
const deliveryDateStr = deliveryDate.toISOString().split("T")[0];

// --- Calculate Delivery Status: compare email sent date vs delivery date ---
const rawReceived = $('Gmail Trigger').first().json.headers?.received
  || $('Gmail Trigger').first().json.date;

const cleanedReceivedStr = extractDateFromReceivedHeader(rawReceived);
const emailSentDate = new Date(cleanedReceivedStr);

let deliveryStatus = "Unknown";
let daysDiff = null;

if (!isNaN(emailSentDate.getTime()) && !isNaN(deliveryDate.getTime())) {
  const emailDay = new Date(emailSentDate.getFullYear(), emailSentDate.getMonth(), emailSentDate.getDate());
  const deliveryDay = new Date(deliveryDate.getFullYear(), deliveryDate.getMonth(), deliveryDate.getDate());

  daysDiff = Math.round((emailDay - deliveryDay) / (1000 * 60 * 60 * 24));

  if (daysDiff < 0) {
    deliveryStatus = "On Track";
  } else if (daysDiff > 2) {
    deliveryStatus = "Delayed";
  } else {
    deliveryStatus = "Delivered";
  }
}

const results = [];

for (const [city, cityProducts] of Object.entries(groups)) {
  const cityCode = cityCodeMap[city] || "GEN";
  const orderId = `${cityCode}-${Date.now()}`;

  for (const product of cityProducts) {
    results.push({
      json: {
        "Order ID": orderId,
        "Date Of Order": order["Date Of Order"],
        "Customer Name": order["Customer Name"],
        "Email Address": order["Email Address"],
        "Shipping Address": order["Shipping Address"],
        "Contact": order["Contact"],

        "SKU": product["SKU"],
        "Category": product["Category"],
        "Product Name": product["Product Name"],
        "Color": product["Color"],
        "Size": product["Size"],
        "Quantity": product["Quantity"],
        "Unit Price (PKR)": product["Unit Price (PKR)"],
        "Line Total (PKR)": product["Line Total (PKR)"],
        "Availability": product["Availability"],
        "Warehouse Location": product["Warehouse Location"],

        "Delivery Date": deliveryDateStr,
        "Delivery Status": deliveryStatus,
        daysSinceDeliveryDate: daysDiff
      }
    });
  }
}

return results;

