const results = [];

// Extracts a parseable date from a raw email "received" header block,
// which contains routing info before the actual date (e.g. "...by mx.google.com... Wed, 15 Jul 2026 22:20:21 -0700 (PDT)")
function extractDateFromReceivedHeader(raw) {
  if (!raw) return null;
  // Match a standard RFC 2822-style date at the end of the string, e.g. "Wed, 15 Jul 2026 22:20:21 -0700"
  const match = raw.toString().match(/\w{3},\s\d{1,2}\s\w{3}\s\d{4}\s\d{2}:\d{2}:\d{2}\s[+-]\d{4}/);
  return match ? match[0] : raw;
}

// Robustly parses a "Delivery Date" that might be "2026-07-19", "19 Jul 2026", etc.
function parseFlexibleDate(raw) {
  if (!raw) return new Date(NaN);
  const cleaned = raw.toString().trim();
  const d = new Date(cleaned);
  return d;
}

for (let i = 0; i < $input.all().length; i++) {
  const data = $input.all()[i].json.output;

  // --- 1. Check if an order was found at all ---
  const orderFound = (data["Order Found"] || "").toString().trim().toLowerCase() === "yes";

  if (!orderFound) {
    results.push({
      json: {
        ...data,
        "Order Found": "No",
        isValid: false,
        validationError: "No matching order was found for this request.",
        "Delivery Status": "Unknown"
      },
      pairedItem: { item: i }
    });
    continue;
  }

  // --- 2. Check that essential fields aren't missing/placeholder values ---
  const requiredFields = [
    "Order ID", "Customer Name", "Email Address", "SKU",
    "Product Name", "Delivery Date"
  ];

  const missingFields = requiredFields.filter(field => {
    const val = (data[field] || "").toString().trim().toLowerCase();
    return val === "" || val === "not found" || val === "not provided";
  });

  if (missingFields.length > 0) {
    results.push({
      json: {
        ...data,
        isValid: false,
        validationError: `Order record is incomplete. Missing: ${missingFields.join(", ")}`,
        "Delivery Status": "Unknown"
      },
      pairedItem: { item: i }
    });
    continue;
  }

  // --- 3. Recalculate Delivery Status ourselves ---
  const rawReceived = $('Gmail Trigger').first().json.headers?.received
    || $('Gmail Trigger').first().json.date;

  const cleanedReceivedStr = extractDateFromReceivedHeader(rawReceived);
  const emailDate = new Date(cleanedReceivedStr);
  const deliveryDate = parseFlexibleDate(data["Delivery Date"]);

  let deliveryStatus = "Unknown";
  let daysDiff = null;
  let parseWarning = null;

  if (!isNaN(emailDate.getTime()) && !isNaN(deliveryDate.getTime())) {
    const emailDay = new Date(emailDate.getFullYear(), emailDate.getMonth(), emailDate.getDate());
    const deliveryDay = new Date(deliveryDate.getFullYear(), deliveryDate.getMonth(), deliveryDate.getDate());

    daysDiff = Math.round((emailDay - deliveryDay) / (1000 * 60 * 60 * 24));

    if (daysDiff < 0) {
      deliveryStatus = "On Track";
    } else if (daysDiff > 2) {
      deliveryStatus = "Delayed";
    } else {
      deliveryStatus = "Delivered";
    }
  } else {
    parseWarning = `Could not parse dates. emailDate raw: "${rawReceived}" -> "${cleanedReceivedStr}" (valid: ${!isNaN(emailDate.getTime())}); deliveryDate raw: "${data["Delivery Date"]}" (valid: ${!isNaN(deliveryDate.getTime())})`;
  }

  results.push({
    json: {
      ...data,
      isValid: true,
      validationError: null,
      "Delivery Status": deliveryStatus,
      daysSinceDeliveryDate: daysDiff,
      _dateDebug: parseWarning
    },
    pairedItem: { item: i }
  });
}

return results;

