const item = $input.item.json.output;

const hasOrderId = item["Order ID"] && item["Order ID"] !== "Not Provided";
const hasName = item["Customer Name"] && item["Customer Name"] !== "Not Provided";
const hasEmail = item["Email Address"] && item["Email Address"] !== "Not Provided";

// Primary mode requires Order ID + Name + Email all present together
const hasFullIdentity = hasOrderId && hasName && hasEmail;

const firstItem = item.Items?.[0] || item;

return {
  json: {
    ...item,
    searchMode: hasFullIdentity ? "orderIdNameEmail" : "nameProductSku",
    searchOrderId: hasOrderId ? item["Order ID"] : null,
    searchCustomerName: firstItem["Customer Name"],
    searchEmail: item["Email Address"],
    searchProductName: firstItem["Product Name"],
    searchSku: firstItem["SKU"]
  }
};

const criteria = $('Build Search Criteria1').item.json;
const normalize = (str) => (str || "").toString().trim().toLowerCase();
const hasSku = criteria.searchSku && normalize(criteria.searchSku) !== "not provided";

// --- Step 1: find matching row(s), same logic as before ---
const matches = [];
for (const item of $input.all()) {
  const row = item.json;
  let isMatch;

  if (criteria.searchMode === "orderIdNameEmail") {
    const orderIdMatches = normalize(row["Order ID"]) === normalize(criteria.searchOrderId);
    const nameMatches = normalize(row["Customer Name"]) === normalize(criteria.searchCustomerName);
    const emailMatches = normalize(row["Email Address"]) === normalize(criteria.searchEmail);
    const skuMatches = hasSku ? normalize(row["SKU"]) === normalize(criteria.searchSku) : true;
    isMatch = orderIdMatches && nameMatches && emailMatches && skuMatches;
  } else if (hasSku) {
    isMatch = normalize(row["SKU"]) === normalize(criteria.searchSku)
              && normalize(row["Customer Name"]) === normalize(criteria.searchCustomerName);
  } else {
    const nameMatches = normalize(row["Customer Name"]) === normalize(criteria.searchCustomerName);
    const productMatches = normalize(row["Product Name"]).includes(normalize(criteria.searchProductName).replace(/\bshirt\b/g, "").trim())
                            || normalize(criteria.searchProductName).includes(normalize(row["Product Name"]));
    isMatch = nameMatches && productMatches;
  }

  if (isMatch) matches.push(row);
}

// --- Step 2: determine the verdict ---
let verdict = "";
let verdictDetail = "";
let matchedOrder = null;

// Helper to strip "PKR", commas, spaces from an amount string and parse as a number
const parseAmount = (val) => {
  if (!val) return null;
  const num = parseFloat(val.toString().replace(/[^0-9.]/g, ""));
  return isNaN(num) ? null : num;
};

const claimedIssueType = criteria["Issue Type"]; // from the extraction agent's classification
const statedCharged = parseAmount(criteria["Amount Charged (As Stated By Customer)"]);
const statedExpected = parseAmount(criteria["Expected Amount (As Stated By Customer)"]);

if (matches.length === 0) {
  // No order found at all — if customer claims a failed transaction, this is consistent.
  // If they claim incorrect amount / refund issue but there's no order on record, that's a real problem too.
  verdict = "Transaction Failed";
  verdictDetail = "No matching order record was found. This is consistent with a failed transaction, or the order/payment details provided do not match our records.";
} else {
  matchedOrder = matches.sort((a, b) => new Date(b["Date Of Order"]) - new Date(a["Date Of Order"]))[0];
  const actualTotal = parseAmount(matchedOrder["Total Amount (PKR)"] || matchedOrder["Line Total (PKR)"]);

  if (claimedIssueType === "Incorrect Amount") {
    if (statedCharged !== null && actualTotal !== null && statedCharged !== actualTotal) {
      verdict = "Wrong Amount Charged";
      verdictDetail = `Customer states they were charged PKR ${statedCharged}, but the order record shows a total of PKR ${actualTotal}. Discrepancy of PKR ${Math.abs(statedCharged - actualTotal)}.`;
    } else if (statedCharged !== null && actualTotal !== null && statedCharged === actualTotal) {
      verdict = "Amount Matches - No Discrepancy Found";
      verdictDetail = `Customer states they were charged PKR ${statedCharged}, which matches the order record total of PKR ${actualTotal}. No discrepancy found.`;
    } else {
      verdict = "Wrong Amount Charged";
      verdictDetail = "Customer claims an incorrect amount was charged, but the stated or actual amount could not be confidently compared. Manual review recommended.";
    }
  } else if (claimedIssueType === "Refund Not Processed") {
    verdict = "Refund Not Received";
    verdictDetail = "Order was found on record. Customer states a refund was expected but not received. Refund status requires manual verification, as it is not currently tracked in this sheet.";
  } else if (claimedIssueType === "Failed Transaction") {
    verdict = "Transaction Failed";
    verdictDetail = "Customer reports a failed transaction, but a matching order WAS found on record. This may mean the payment actually succeeded, or a duplicate/separate failed attempt occurred. Manual review recommended.";
  } else {
    verdict = "Unclear - Manual Review Needed";
    verdictDetail = "Could not determine a clear verdict from the available data.";
  }
}

return [{
  json: {
    ...criteria,
    matchedOrder,
    orderFound: matches.length > 0,
    verdict,
    verdictDetail
  }
}];

