const results = [];

for (const item of $input.all()) {
  const data = item.json.output || item.json;

  const orderFound = (data.orderFound || "").toString().trim().toLowerCase() === "yes";

  if (!orderFound) {
    results.push({
      json: {
        ...data,
        isValid: false,
        validationError: "No matching order was found for this cancellation request.",
        orderFound: "No"
      }
    });
    continue;
  }

  // Order was found — check the matched record actually has usable data
  const requiredFields = ["orderId", "customerName", "emailAddress", "productName"];

  const missingFields = requiredFields.filter(field => {
    const val = (data[field] || "").toString().trim().toLowerCase();
    return val === "" || val === "not found" || val === "not provided";
  });

  if (missingFields.length > 0) {
    results.push({
      json: {
        ...data,
        isValid: false,
        validationError: `Matched order record is incomplete. Missing: ${missingFields.join(", ")}`,
        orderFound: "Yes"
      }
    });
    continue;
  }

  results.push({
    json: {
      ...data,
      isValid: true,
      validationError: null,
      orderFound: "Yes"
    }
  });
}

return results;
